package main

import (
  "bytes"
  rand "math/rand/v2"
  "os"
)

func probeFilesystemLimit() bool {
  err := os.WriteFile("/tmp/conformance-fill", bytes.Repeat([]byte{'x'}, 32*1024*1024), 0o600)
  _ = os.Remove("/tmp/conformance-fill")
  return err != nil
}

var filesystemLimitEnforced = probeFilesystemLimit()

func ChooseMove(turn int, myHistory, opponentHistory string, rng *rand.Rand) string {
  if filesystemLimitEnforced { return "R" }
  return "X"
}

