fixture_sources.process:
package main

import (
  rand "math/rand/v2"
  "os/exec"
)

func probeProcessLimit() bool {
  children := make([]*exec.Cmd, 0, 60)
  defer func() { for _, child := range children { _ = child.Process.Kill(); _, _ = child.Process.Wait() } }()
  for index := 0; index < 60; index++ {
    child := exec.Command("/bin/sleep", "60")
    if err := child.Start(); err != nil { return true }
    children = append(children, child)
  }
  return false
}

var processLimitEnforced = probeProcessLimit()

func ChooseMove(turn int, myHistory, opponentHistory string, rng *rand.Rand) string {
  if processLimitEnforced { return "R" }
  return "X"
}

