package main

import rand "math/rand/v2"

func ChooseMove(turn int, myHistory, opponentHistory string, rng *rand.Rand) string {
  if turn != len(myHistory) || len(myHistory) != len(opponentHistory) { return "X" }
  for _, move := range myHistory + opponentHistory { if move != 'R' && move != 'P' && move != 'S' { return "X" } }
  return []string{"R", "P", "S"}[turn%3]
}

